\usepackage{listings}

\begin{document}
  \maketitle
  \frontmatter
  \tableofcontents

  \mainmatter % start numbering pages from here

  \chapter{First Chapter}

  \lstlisting[language=python]{example_code.py}

  \chapter{Second Chapter}

  \section{Section One}
  \lstlisting[language=r]{example_r_code.R}

  \section{Section Two}
  \subsection{Sub-Section A}
  \lstlisting[language=cpp]{example_cpp_code.cpp}

  \subsection{Sub-Section B}
  \lstlisting[language=java]{example_java_code.java}

%\backmatter  % end with back matter, added for book class
\end{document}
```

